// core: FedAvg-style aggregation of client weight vectors
const clients=[[0.8,0.2,-0.1],[0.7,0.3,0.0],[0.9,0.1,-0.2],[0.75,0.25,-0.05]];const sizes=[100,80,60,40];
const totalW=sizes.reduce((a,b)=>a+b,0);
const global=clients[0].map((_,j)=>clients.reduce((a,c,i)=>a+c[j]*sizes[i],0)/totalW);
const drift=clients.map(c=>Math.sqrt(c.reduce((a,w,j)=>a+(w-global[j])**2,0)));
J({global:global.map(v=>+v.toFixed(4)),max_client_drift:+Math.max(...drift).toFixed(4),rounds:1});assert(global.length===3,'dims');assert(Math.max(...drift)<0.3,'converging');

// end-to-end: 3 federated rounds, accuracy improves, updates stay local
let acc=0.62;const rounds=[];for(let r=1;r<=3;r++){acc=+(acc+0.06).toFixed(2);rounds.push({round:r,accuracy:acc,participants:4,data_shipped_bytes:0,updates_kb:128});}
J({rounds,final_accuracy:acc,data_left_devices:true});assert(Math.abs(acc-0.8)<1e-9,'accuracy');assert(rounds.every(r=>r.data_shipped_bytes===0),'privacy');
